def fibonacci(n):
    if n <= 0:
        return "Invalid input, please enter a positive integer."
    elif n == 1 or n == 2:
        return 1
    else:
        fib_sequence = [1, 1]
        for i in range(2, n):
            next_num = fib_sequence[i-1] + fib_sequence[i-2]
            fib_sequence.append(next_num)
        return fib_sequence[n-1]

